/* ─── HELPERS ────────────────────────────────────────────── */

/** Normalize category tags on a word to a lowercase string array */
export function getWordCategories(entry: VocabularyEntry): string[] {
  const raw = Array.isArray(entry.category)
    ? entry.category
    : [entry.category];
  return raw.map((c) => c.trim().toLowerCase()).filter(Boolean);
}

/**
 * Does this word belong to the given category id or title?
 * Matches case-insensitively against any tag on the word.
 */
export function wordBelongsTo(
  entry: VocabularyEntry,
  categoryIdOrTitle: string
): boolean {
  const target = categoryIdOrTitle.trim().toLowerCase();
  return getWordCategories(entry).includes(target);
}

/** All words that belong to a category (id or title) */
export function getWordsByCategory(
  categoryIdOrTitle: string
): VocabularyEntry[] {
  return vocabulary.filter((w) => wordBelongsTo(w, categoryIdOrTitle));
}

/** Count of words in a category */
export function countWordsByCategory(categoryIdOrTitle: string): number {
  return getWordsByCategory(categoryIdOrTitle).length;
}

/**
 * Words for the "General Words" strip.
 * Prefer entries tagged "General"; fall back to a sample of everything.
 */
export function getGeneralWords(limit = 6): VocabularyEntry[] {
  const tagged = vocabulary.filter((w) => wordBelongsTo(w, "General"));
  const pool = tagged.length > 0 ? tagged : vocabulary;
  return pool.slice(0, limit);
}

/** Look up a single word by id */
export function getWordById(
  id: number | string
): VocabularyEntry | undefined {
  return vocabulary.find((w) => String(w.id) === String(id));
}

/** Unique category tags present in the data (lowercase) */
export function getUsedCategoryTags(): string[] {
  const set = new Set<string>();
  vocabulary.forEach((w) => getWordCategories(w).forEach((c) => set.add(c)));
  return Array.from(set);
}